def primes_up_to(n: int) -> list[int]:
    sieve = [True] * (n+1)
    p = 2
    while p * p <= n:
        if sieve[p] is True:
            for i in range(p * p, n+1, p):
                sieve[i] = False
        p += 1

    primes = [p for p in range(2, n) if sieve[p]]
    return primes

