def mean_and_median(numbers: list[float]) -> tuple[float, float]:
    n = len(numbers)
    numbers.sort()
    mean = sum(numbers) / n
    if n % 2 == 0:
        median = (numbers[n//2 - 1] + numbers[n//2]) / 2
    else:
        median = numbers[n//2]
    return mean, median

