import os
import mimetypes

def serve_static(web_root: str, request_path: str) -> tuple[int, bytes]:
    full_path = os.path.join(web_root, request_path.lstrip('/'))

    if not os.path.exists(full_path):
        return 404, b'File not found'

    if os.path.isdir(full_path):
        return 403, b'Forbidden'

    content_type, _ = mimetypes.guess_type(full_path)
    with open(full_path, 'rb') as file:
        file_data = file.read()

    return 200, file_data, {'Content-Type': content_type}

