from collections import Counter

def compute_mode(nums: list[int]) -> list[int]:
    if not nums:
        return []
    count = Counter(nums)
    max_count = max(count.values())
    modes = [num for num, freq in count.items() if freq == max_count]
    return sorted(modes)
