def mean_and_median(numbers: list[float]) -> tuple[float, float]:
    numbers.sort()
    length = len(numbers)
    mean = sum(numbers) / length
    if length % 2 == 0:
        median = (numbers[length // 2 - 1] + numbers[length // 2]) / 2
    else:
        median = numbers[length // 2]
    return round(mean, 2), round(median, 2)
