def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return '0'
    res = []
    while n:
        n, remainder = divmod(n, 3)
        if remainder < 0:
            remainder -= 3
            n += 1
        res.append(str(remainder))
    return ''.join(res[::-1])
