def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return '0'
    res = []
    while n != 0:
        rem = n % 3
        n //= 3
        if rem < 0:
            rem -= 3
            n += 1
        res.append(str(rem))
    return ''.join(res[::-1])
