def compress_string(s: str) -> str:
    if not s:
        return s
    compressed = []
    i = 0
    while i < len(s):
        count = 1
        while i + 1 < len(s) and s[i] == s[i + 1]:
            i += 1
            count += 1
        compressed.append(s[i] + str(count))
        i += 1
    compressed_str = ''.join(compressed)
    if len(compressed_str) < len(s):
        return compressed_str
    else:
        return s
