def min_max_normalize(nums: list[float]) -> list[float]:
    if not nums:
        return []
    min_num = min(nums)
    max_num = max(nums)
    range_num = max_num - min_num
    if range_num == 0:
        return [0.0] * len(nums)
    return [round((num - min_num) / range_num, 2) for num in nums]
