import tarfile
import gzip

def extract_tar(tar_path: str, dest_dir: str) -> None:
    if not os.path.exists(tar_path):
        raise FileNotFoundError(f"File {tar_path} does not exist.")

    if not os.path.isdir(dest_dir):
        raise NotADirectoryError(f"Directory {dest_dir} does not exist.")

    if tar_path.endswith('.tar.gz'):
        with gzip.open(tar_path, 'rb') as tar_gz:
