import operator

def matches_filter(expression: str, record: dict) -> bool:
    valid_operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.USub: operator.neg,
        ast.BitAnd: operator.and_,
        ast.BitOr: operator.or_,
        ast.Not: operator.not_,
        ast.Lt: operator.lt,
        ast.LtE: operator.le,
        ast.Gt: operator.gt,
        ast.GtE: operator.ge,
        ast.Eq: operator.eq,
        ast.NotEq: operator.ne,
    }

    def visit_BinOp(node):
        if isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div, ast.BitAnd, ast.BitOr)):
            return valid_operators[type(node.op)](visit_BinOp(node.left), visit_BinOp(node.right))
        elif isinstance(node.op, (ast.Lt, ast.LtE, ast.Gt, ast.GtE, ast.Eq, ast.NotEq)):
            left_val = visit_BinOp(node.left) if isinstance(node.left, ast.BinOp) else node.left.n
            right_val = visit_BinOp(node.right) if isinstance(node.right, ast.BinOp) else node.right.n
            return valid_operators[type(node.op)](left_val, right_val)
        elif isinstance(node.op, ast.Not):
            return valid_operators[type(node.op)](visit_BinOp(node.right))
        else:
            raise ValueError("Invalid operator")

    try:
        return ast.parse(expression, mode='eval').body
    except SyntaxError:
        raise ValueError("Invalid expression")

