import operator
import ast

def matches_filter(expression: str, record: dict) -> bool:
    allowed_operators = {ast.Add: operator.add, ast.Sub: operator.sub,
                         ast.Mult: operator.mul, ast.Div: operator.truediv,
                         ast.USub: operator.neg, ast.BitAnd: operator.and_,
                         ast.BitOr: operator.or_, ast.Gt: operator.gt,
                         ast.Lt: operator.lt, ast.GtE: operator.ge,
                         ast.LtE: operator.le, ast.Eq: operator.eq,
                         ast.NotEq: operator.ne, ast.Not: operator.not_}

    try:
        tree = ast.parse(expression, mode='eval').body
        if not isinstance(tree, ast.Compare):
            raise ValueError
        left = tree.left
        if not isinstance(left, ast.Name):
            raise ValueError
        if left.id not in record:
            raise ValueError
        for op in tree.ops:
            if not isinstance(op, (ast.Gt, ast.Lt, ast.GtE, ast.LtE, ast.Eq, ast.NotEq)):
                raise ValueError
        for comp in tree.comparators:
            if not isinstance(comp, (ast.Num, ast.Name)):
                raise ValueError
    except:
        raise ValueError("Invalid expression")

    for node in ast.walk(tree):
        if isinstance(node, ast.Compare):
            continue
        if isinstance(node, ast.Name):
            if node.id not in record:
                raise ValueError("Invalid expression")
        if isinstance(node, (ast.Num, ast.BinOp)):
            continue
        raise ValueError("Invalid expression")

    for node in ast.walk(tree):
        if isinstance(node, ast.BinOp):
            op_func = allowed_operators[type(node.op)]
            left = node.left if isinstance(node.left, ast.Num) else record[node.left.id]
            right = node.right if isinstance(node.right, ast.Num) else record[node.right.id]
            record[node.left.id] = op_func(left, right)
        if isinstance(node, ast.Compare):
            left = record[node.left.id]
            for i, op in enumerate(node.ops):
                op_func = allowed_operators[type(op)]
                right = node.comparators[i]
                right = right.n if isinstance(right, ast.Num) else record[right.id]
                if not op_func(left, right):
                    return False
                left = record[node.left.id]
    return True
