def evaluate_formula(formula: str, x: float) -> float:
    operators = {ast.Add: op.add, ast.Sub: op.sub, ast.Mult: op.mul,
                 ast.Div: op.truediv, ast.Pow: op.pow, ast.USub: op.neg}

    functions = {
        'sqrt': math.sqrt,
        'abs': abs,
        'sin': math.sin,
        'cos': math.cos
    }

    parsed = ast.parse(formula, mode='eval').body

    if not isinstance(parsed, ast.Expression):
        raise ValueError("Invalid formula")

    for node in ast.walk(parsed):
        if isinstance(node, ast.Name) and node.id in ['x', 'sin', 'cos', 'sqrt', 'abs']:
            node.id = functions[node.id]

    for node in ast.walk(parsed):
        if isinstance(node, ast.BinOp):
            node.op = operators[type(node.op)]

    try:
        return eval(compile(parsed, filename='<ast>', mode='eval'))
