                value = float(value)
            except ValueError:
                if value.lower() not in ['true', 'false']:
                    raise ValueError("Invalid value in expression")
            if op == '==':
                if isinstance(record[key], str):
                    return record[key] == value
                else:
                    return record[key] == float(value)
            elif op == '!=':
                if isinstance(record[key], str):
                    return record[key] != value
                else:
                    return record[key] != float(value)
            elif op == '<':
                return record[key] < float(value)
            elif op == '<=':
                return record[key] <= float(value)
            elif op == '>':
                return record[key] > float(value)
            elif op == '>=':
                return record[key] >= float(value)
            elif op == 'and':
                return record[key] and value
            elif op == 'or':
                return record[key] or value
            elif op == 'not':
                return not record[key]
    raise ValueError("Invalid expression")
