import math
import ast

class FormulaEvaluator(ast.NodeTransformer):
    def visit_BinOp(self, node):
        if isinstance(node.op, ast.Add):
            return ast.Num(n=self.visit(node.left).n + self.visit(node.right).n)
        elif isinstance(node.op, ast.Sub):
            return ast.Num(n=self.visit(node.left).n - self.visit(node.right).n)
        elif isinstance(node.op, ast.Mult):
            return ast.Num(n=self.visit(node.left).n * self.visit(node.right).n)
        elif isinstance(node.op, ast.Div):
            if self.visit(node.right).n == 0:
                raise ZeroDivisionError("division by zero")
            return ast.Num(n=self.visit(node.left).n / self.visit(node.right).n)
        elif isinstance(node.op, ast.Pow):
            return ast.Num(n=self.visit(node.left).n ** self.visit(node.right).n)
        else:
            raise ValueError("unsupported operator")

    def visit_UnaryOp(self, node):
        if isinstance(node.op, ast.USub):
            return ast.Num(n=-self.visit(node.operand).n)
        else:
            raise ValueError("unsupported unary operator")

    def visit_Call(self, node):
        if isinstance(node.func, ast.Name):
            if node.func.id == 'sqrt':
                return ast.Num(n=math.sqrt(self.visit(node.args[0]).n))
            elif node.func.id == 'abs':
                return ast.Num(n=abs(self.visit(node.args[0]).n))
            elif node.func.id == 'sin':
                return ast.Num(n=math.sin(math.radians(self.visit(node.args[0]).n)))
            elif node.func.id == 'cos':
                return ast.Num(n=math.cos(math.radians(self.visit(node.args[0]).n)))
            else:
                raise ValueError("unsupported function")
        else:
            raise ValueError("unsupported function call")

def evaluate_formula(formula: str, x: float) -> float:
    tree = ast.parse(formula, mode='eval').body
    for node in ast.walk(tree):
        if isinstance(node, ast.Name) and node.id == 'x':
            node.id = 'n'
    tree = FormulaEvaluator().visit(tree)
    return eval(compile(tree, filename='<ast>', mode='eval'))
