    # Check if target is a valid URL
    if not target.lower().startswith(("http://", "https://")):
        return False

    # Check if target host matches the provided host
    if target.lower().split("/")[2].split(":")[0] != host.lower():
        return False

    # Check if target is a site-relative path
    if target.startswith("/"):
        return True

    # Check if target contains any backslash, space or control character
    for char in target:
        if char in ["\\", " ", chr(i) for i in range(32, 128)]:
            return False

    return True
