import math
import ast
import operator as op

class Evaluator(ast.NodeVisitor):
    def __init__(self, x):
        self.x = x
        self.operators = {ast.Add: op.add, ast.Sub: op.sub,
                          ast.Mult: op.mul, ast.Div: op.truediv,
                          ast.Pow: op.pow, ast.BitXor: op.xor}

    def visit_BinOp(self, node):
        left = self.visit(node.left)
        right = self.visit(node.right)
        return self.operators[type(node.op)](left, right)

    def visit_UnaryOp(self, node):
        operand = self.visit(node.operand)
        return op.neg(operand) if type(node.op) is ast.USub else operand

    def visit_Num(self, node):
        return node.n

    def visit_NameConstant(self, node):
        return node.value

    def visit_Call(self, node):
        func_name = node.func.id
        if func_name == 'sqrt':
            return math.sqrt(self.visit(node.args[0]))
        elif func_name == 'abs':
            return math.fabs(self.visit(node.args[0]))
        elif func_name == 'sin':
            return math.sin(math.radians(self.visit(node.args[0])))
        elif func_name == 'cos':
            return math.cos(math.radians(self.visit(node.args[0])))
        else:
            raise ValueError(f"Unknown function {func_name}")

def evaluate_formula(formula: str, x: float) -> float:
    try:
        tree = ast.parse(formula, mode='eval').body
        return Evaluator(x).visit(tree)
    except (SyntaxError, TypeError, ZeroDivisionError, ValueError):
        raise ValueError("Invalid formula")
