import ast
import sympy

OPERATORS = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul,
             ast.Div: operator.truediv, ast.Pow: operator.pow, ast.USub: operator.neg}

FUNCTIONS = {
    'sqrt': math.sqrt,
    'abs': abs,
    'sin': math.sin,
    'cos': math.cos,
}

def evaluate_formula(formula: str, x: float) -> float:
    try:
        node = ast.parse(formula, mode='eval').body
        if not isinstance(node, (ast.Num, ast.BinOp, ast.UnaryOp, ast.Call)):
            raise ValueError
        return eval_expr(node, x)
    except (SyntaxError, TypeError, ZeroDivisionError, ValueError):
        raise ValueError("Invalid formula")

def eval_expr(node, x):
    if isinstance(node, ast.Num):
        return node.n
    elif isinstance(node, ast.BinOp):
        return OPERATORS[type(node.op)](eval_expr(node.left, x), eval_expr(node.right, x))
    elif isinstance(node, ast.UnaryOp):
        return OPERATORS[type(node.op)](eval_expr(node.operand, x))
    elif isinstance(node, ast.Call):
        args = [eval_expr(arg, x) for arg in node.args]
        if node.func.id in FUNCTIONS:
            return FUNCTIONS[node.func.id](*args)
        else:
            raise ValueError("Invalid function")
    else:
        raise ValueError("Invalid expression")
