        try:
            return float(token)
        except ValueError:
            if token in OPERATORS or token in UNARY_MINUS:
                return token
            elif token in FUNCTIONS:
                return FUNCTIONS[token]
            else:
                raise ValueError(f"Invalid token: {token}")

    def shunting_yard(tokens):
        output_queue = []
        operator_stack = []

        for token in tokens:
            if isinstance(parse_token(token), float) or token == '(':
                output_queue.append(token)
            elif token == ')':
                while operator_stack and operator_stack[-1] != '(':
                    output_queue.append(operator_stack.pop())
                operator_stack.pop()
            else:
