                    output_queue.append(operator_stack.pop())
                operator_stack.append(token)

        while operator_stack:
            output_queue.append(operator_stack.pop())

        return output_queue

    def calculate(rpn):
        stack = []

        for token in rpn:
            if isinstance(parse_token(token), float):
                stack.append(token)
            else:
