def balanced_ternary_str(n: int) -> str:
    if n == 0:
        return '0'
    res = ''
    while n != 0:
        remainder = n % 3
        n //= 3
        if remainder < 0:
            remainder += 3
            n += 1
        res = '01-'[remainder] + res
    return res

