def rolling_variance(nums: list[float], k: int) -> list[float]:
    if k > len(nums) or k <= 0:
        return []
    else:
        means = [sum(nums[i-k:i])/k for i in range(k, len(nums)+1)]
        variances = [round(sum((x - means[i]) ** 2 for x in nums[i-k:i]) / k, 3) for i in range(k, len(nums)+1)]
        return variances
