import re

def is_allowed_webhook(url: str) -> bool:
    # Check if url starts with 'https://'
    if not url.lower().startswith('https://'):
        return False

    # Check if url contains any backslash, space, or control character
    if any(c < 32 or c > 127 for c in map(ord, url)):
        return False

    # Check if url contains any host that is not a DNS name
    if re.search(r'[^a-z0-9-]', url.split('/')[2].split(':')[0]):
        return False

    # Check if url contains 'localhost' or '.localhost'
    if 'localhost' in url.split('/')[2] or '.localhost' in url.split('/')[2]:
        return False

    # Check if url contains a port other than 443
    if ':' in url.split('/')[2] and url.split('/')[2].split(':')[1] != '443':
        return False

    return True

