import string

def is_allowed_webhook(url: str) -> bool:
    # Check if URL starts with 'https://'
    if not url.startswith('https://'):
        return False

    # Check if URL contains any backslash, space, or control character
    if any(c in url for c in '\\/:*?"<>|\r\n\t'):
        return False

    # Check if URL contains any non-ASCII character
    if not all(c in string.printable for c in url):
        return False

    # Check if host is a valid DNS name
    host = url.split('/')[2].split(':')[0]
    if not re.match(r'^([a-zA-Z0-9-]+\.)*[a-zA-Z0-9-]+\.[a-zA-Z]{2,}$', host):
        return False

    # Check if host is not 'localhost' or ends with '.localhost'
    if host in ['localhost', 'localhost.']:
        return False

    # Check if port is 443
    if ':' in url and url.split(':')[2] != '443':
        return False

    return True

